CREATE OR REPLACE FUNCTION submit_match_result(p_match_id UUID, p_home_score INT, p_away_score INT, p_home_penalties INT DEFAULT NULL, p_away_penalties INT DEFAULT NULL, p_sets_data JSONB DEFAULT NULL, p_details TEXT DEFAULT NULL, p_events JSONB DEFAULT '[]'::jsonb) RETURNS match_result_submissions AS $$ DECLARE v_user_id UUID; v_result match_result_submissions; BEGIN v_user_id := auth.uid(); IF v_user_id IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF; INSERT INTO match_result_submissions (match_id, submitted_by, home_score, away_score, home_penalties, away_penalties, sets_data, details, events, status) VALUES (p_match_id, v_user_id, p_home_score, p_away_score, p_home_penalties, p_away_penalties, p_sets_data, p_details, p_events, 'PENDING') ON CONFLICT (match_id) DO UPDATE SET home_score = EXCLUDED.home_score, away_score = EXCLUDED.away_score, home_penalties = EXCLUDED.home_penalties, away_penalties = EXCLUDED.away_penalties, sets_data = EXCLUDED.sets_data, details = EXCLUDED.details, events = EXCLUDED.events, status = 'PENDING', submitted_at = NOW(), rejection_reason = NULL RETURNING * INTO v_result; RETURN v_result; END; $$ LANGUAGE plpgsql SECURITY DEFINER;
